package syncbus

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"path"
	"sort"
	"strings"

	"github.com/BurntSushi/toml"
)

// planMCPFragment plans the MCP servers of a Codex Profile whose config.toml
// is regenerated by something else: they go into a TOML file of Baton's, which
// the Runtime merges into the config it renders. The fragment is an ordinary
// file of Baton's, so the rules of owned files apply to it. It holds secrets,
// so it is created with mode 0600.
func (b *Bus) planMCPFragment(ctx context.Context, plan *profilePlan, servers mcpServers, owned, wantedFiles map[string]bool, res *Result) error {
	data, warnings, err := codexMCPFragment(servers)
	if err != nil {
		return err
	}
	for _, w := range warnings {
		res.Warnings = append(res.Warnings, fmt.Sprintf("profile %s: %s", plan.profile.Name, w))
	}
	if data == nil {
		return nil
	}
	wantedFiles[mcpFragmentFile] = true
	return b.planOwnedFile(ctx, plan, owned, mcpFragmentFile, File{Path: path.Base(mcpFragmentFile), Mode: 0o600, Data: data})
}

// codexMCPFragment renders servers in the shape of Codex's config.toml:
// `[mcp_servers.<name>]` tables. Codex has stdio servers and streamable HTTP
// servers; a server of another kind is left out with a warning. The result is
// nil when no server is left.
func codexMCPFragment(servers mcpServers) (data []byte, warnings []string, err error) {
	tables, warnings := codexServers(servers.names, servers.values, true)
	if len(tables) == 0 {
		return nil, warnings, nil
	}

	var buf bytes.Buffer
	enc := toml.NewEncoder(&buf)
	enc.Indent = ""
	if err := enc.Encode(map[string]any{"mcp_servers": tables}); err != nil {
		return nil, nil, fmt.Errorf("render MCP servers for Codex: %w", err)
	}
	// The encoder opens with an empty `[mcp_servers]` header. A config that
	// has its own `[mcp_servers]` table would then define it twice, which TOML
	// forbids, so only the tables of the servers are kept.
	body := strings.TrimPrefix(buf.String(), "[mcp_servers]\n")
	return []byte("# Written by baton sync. Do not edit.\n" + body), warnings, nil
}

// codexServers converts the named servers of mcp.json (Claude's shape, in
// specs) into the tables Codex reads, by name. A server that Codex cannot run
// is left out, and members it has no equivalent for are dropped; both are
// warnings when warn is set (the same servers are converted twice, with and
// without their secrets, and the second time says nothing).
func codexServers(names []string, specs map[string]any, warn bool) (tables map[string]any, warnings []string) {
	tables = make(map[string]any, len(names))
	for _, name := range names {
		spec, _ := specs[name].(map[string]any)
		table, why := toCodexServer(spec)
		if why != "" {
			warnings = append(warnings, fmt.Sprintf("mcp.json: server %q %s; it is not written for Codex", name, why))
			continue
		}
		tables[name] = table
		for _, key := range unusedKeys(spec) {
			warnings = append(warnings, fmt.Sprintf("mcp.json: server %q: %q has no Codex equivalent and is left out", name, key))
		}
	}
	if !warn {
		warnings = nil
	}
	return tables, warnings
}

// codexKeys are the members of a server of mcp.json that have a Codex
// equivalent.
var codexKeys = map[string]bool{"type": true, "command": true, "args": true, "env": true, "url": true, "headers": true}

func unusedKeys(spec map[string]any) []string {
	var keys []string
	for k := range spec {
		if !codexKeys[k] {
			keys = append(keys, k)
		}
	}
	sort.Strings(keys)
	return keys
}

// toCodexServer converts a server of mcp.json (Claude's shape) into the table
// Codex reads. why says what is wrong when it cannot.
func toCodexServer(spec map[string]any) (table map[string]any, why string) {
	kind, _ := spec["type"].(string)
	if kind == "" {
		kind = "stdio"
		if _, ok := spec["url"]; ok {
			kind = "http"
		}
	}

	switch kind {
	case "stdio":
		command, ok := spec["command"].(string)
		if !ok || command == "" {
			return nil, "has no command"
		}
		table = map[string]any{"command": command}
		if args, ok := toStrings(spec["args"]); ok && len(args) > 0 {
			table["args"] = args
		}
		if env, ok := toStringMap(spec["env"]); ok && len(env) > 0 {
			table["env"] = env
		}
	case "http":
		url, ok := spec["url"].(string)
		if !ok || url == "" {
			return nil, "has no url"
		}
		table = map[string]any{"url": url}
		if headers, ok := toStringMap(spec["headers"]); ok && len(headers) > 0 {
			table["http_headers"] = headers
		}
	default:
		return nil, fmt.Sprintf("is of type %q, which Codex does not support", kind)
	}
	return table, ""
}

func toStrings(v any) ([]string, bool) {
	list, ok := v.([]any)
	if !ok {
		return nil, false
	}
	out := make([]string, 0, len(list))
	for _, item := range list {
		switch item := item.(type) {
		case string:
			out = append(out, item)
		case json.Number:
			out = append(out, item.String())
		default:
			return nil, false
		}
	}
	return out, true
}

func toStringMap(v any) (map[string]string, bool) {
	m, ok := v.(map[string]any)
	if !ok {
		return nil, false
	}
	out := make(map[string]string, len(m))
	for k, item := range m {
		s, ok := item.(string)
		if !ok {
			return nil, false
		}
		out[k] = s
	}
	return out, true
}
